/usr/bin/bash -lc "sed -n '1,260p' pyproject.toml && python - <<'PY'
import asyncio
from starlette.websockets import WebSocket, WebSocketDisconnect, WebSocketDisconnected, WebSocketState

scope = {\"type\": \"websocket\", \"path\": \"/\", \"headers\": []}

async def no_receive():
    raise AssertionError(\"unexpected receive\")

async def no_send(message):
    raise AssertionError(\"unexpected send\")

async def checks():
    assert issubclass(WebSocketDisconnected, RuntimeError)
    assert WebSocketDisconnected is not RuntimeError

    ws = WebSocket(scope, no_receive, no_send)
    ws.client_state = WebSocketState.DISCONNECTED
    try:
        await ws.receive()
    except WebSocketDisconnected as exc:
        assert str(exc) == 'Cannot call \"receive\" once a disconnect message has been received.'
    else:
        raise AssertionError(\"receive did not raise\")

    ws = WebSocket(scope, no_receive, no_send)
    ws.application_state = WebSocketState.DISCONNECTED
    try:
        await ws.send({\"type\": \"websocket.send\", \"text\": \"x\"})
    except WebSocketDisconnected as exc:
        assert str(exc) == 'Cannot call \"send\" once a close message has been sent.'
    else:
        raise AssertionError(\"send did not raise\")

    for helper in (ws.receive_text, ws.receive_bytes, ws.receive_json):
        try:
            await helper()
        except WebSocketDisconnected as exc:
            assert str(exc) == 'WebSocket is not connected. Need to call \"accept\" first.'
        else:
            raise AssertionError(f\"{helper.__name__} did not raise\")

    try:
        await ws.receive_json(mode=\"invalid\")
    except WebSocketDisconnected:
        raise AssertionError(\"invalid mode raised WebSocketDisconnected\")
    except RuntimeError as exc:
        assert type(exc) is RuntimeError
    else:
        raise AssertionError(\"invalid mode did not raise\")

    messages = iter([{\"type\": \"websocket.disconnect\", \"code\": 1001, \"reason\": \"bye\"}])
    async def peer_disconnect():
        return next(messages)
    ws = WebSocket(scope, peer_disconnect, no_send)
    ws.client_state = WebSocketState.CONNECTED
    ws.application_state = WebSocketState.CONNECTED
    try:
        await ws.receive_text()
    except WebSocketDisconnected:
        raise AssertionError(\"peer disconnect raised WebSocketDisconnected\")
    except WebSocketDisconnect as exc:
        assert exc.code == 1001 and exc.reason == \"bye\"
    else:
        raise AssertionError(\"peer disconnect did not raise\")

asyncio.run(checks())
print(\"direct websocket state checks passed\")
PY"

